// Dependency-free, paginated A4 PDF export. ASCII text keeps byte offsets exact.
import {portfolioStats,odds,formatPct} from './engine.mjs';
const clean=s=>String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^\x20-\x7e]/g,'-');
const escape=s=>clean(s).replace(/([\\()])/g,'\\$1');
export function createReport(selection){
 const money=x=>'R'+x.toFixed(2),date=new Date(selection.created).toLocaleString('en-ZA',{timeZone:'Africa/Johannesburg'});
 const rows=[];const add=(text,kind='text')=>{const t=clean(text);if(t.length<=88){rows.push({text:t,kind});return;}let s=t;while(s.length>88){let cut=s.lastIndexOf(' ',88);if(cut<20)cut=88;rows.push({text:s.slice(0,cut),kind});s=s.slice(cut).trim();}if(s)rows.push({text:s,kind});};
 add('Created '+date+' SAST');add('Selection: '+selection.strategy);add('Generated numbers are not predictions or purchased tickets.');add('All valid combinations have equal odds in a fair draw.');add('');
 let total=0;
 for(const group of selection.groups){const {g,lines}=group,stats=portfolioStats(g,lines);const cost=lines.length*(selection.groups.length>1?g.price:g.entry);total+=cost;
 add(g.name.toUpperCase(),'heading');add(`${g.k} from ${g.n}${g.m?` + ${g.j} from ${g.m}`:''} | ${lines.length} unique lines`);add(`Match all in this draw: ${odds(stats.jackpot)} (${formatPct(stats.jackpot)})`);add(`Cost: ${money(cost)}${selection.groups.length>1?' (this game portion)':' (includes required base games)'}`);add('');
 lines.forEach((l,i)=>add(String(i+1).padStart(3,'0')+'   '+l.main.map(n=>String(n).padStart(2,'0')).join('   ')+(l.extra.length?'    EXTRA: '+l.extra.map(n=>String(n).padStart(2,'0')).join('  '):''),'numbers'));add('');}
 add('TOTAL '+money(total),'heading');add('Retailer / bank fees are not included. Add-on entries reuse the base-game numbers.');add('For a single add-on selection, odds above apply only to its selected draw.');add('Rules reviewed 10 October 2026. Check current rules with your ticket retailer.');
 if(selection.analysis){const a=selection.analysis;add('COVERAGE ANALYSIS','heading');add(`Target: at least ${a.r} main matches${a.extra?' plus every extra ball':''}.`);add(`${a.exact?'Exact result':'Simulation estimate'}: ${formatPct(a.p)}`);if(!a.exact)add(`95% Wilson interval: ${formatPct(a.low)} to ${formatPct(a.high)}; ${a.n} trials.`);}
 add('');add('Sources: Nedbank lottery FAQs; Standard Bank Play Lotto help.');add('Mathematics: Kyle Siegrist, Random Services, Lotteries and finite sampling.');add('18+ | Lotto Lab | Personal selection report');
 const chunks=[];let chunk=[];for(let i=0;i<rows.length;i++){if(rows[i].kind==='heading'&&chunk.length){let next=rows.findIndex((r,j)=>j>i&&r.kind==='heading');if(next<0)next=rows.length;const need=Math.min(12,next-i);if(43-chunk.length<need){chunks.push(chunk);chunk=[];}}if(chunk.length===43){chunks.push(chunk);chunk=[];}chunk.push(rows[i]);}if(chunk.length)chunks.push(chunk);
 const objects=[];const push=s=>{objects.push(s);return objects.length;};push('<< /Type /Catalog /Pages 2 0 R >>');push('');const regular=push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');const bold=push('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>');const mono=push('<< /Type /Font /Subtype /Type1 /BaseFont /Courier >>');const pages=[];
 const txt=(s,x,y,size,font='F1',color='0.20 0.27 0.19')=>`BT /${font} ${size} Tf ${color} rg ${x} ${y} Td (${escape(s)}) Tj ET\n`;
 chunks.forEach((chunk,index)=>{let stream='0.07 0.11 0.08 rg 0 752 595.28 89.89 re f\n';stream+=txt('lotto lab',42,791,25,'F2','0.83 0.96 0.42');stream+=txt('YOUR NUMBERS / SOUTH AFRICA',42,770,9,'F1','0.75 0.80 0.70');let y=727;for(const row of chunk){stream+=txt(row.text,42,y,row.kind==='heading'?12:row.kind==='numbers'?11:9,row.kind==='heading'?'F2':row.kind==='numbers'?'F3':'F1');y-=15.2;}stream+='0.85 0.88 0.82 RG 42 45 m 553 45 l S\n';stream+=txt('LOTTOLAB  |  Generated selection - not a lottery ticket',42,29,8);stream+=txt(`${index+1} / ${chunks.length}`,518,29,8);const content=push(`<< /Length ${stream.length} >>\nstream\n${stream}endstream`);pages.push(push(`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /Font << /F1 ${regular} 0 R /F2 ${bold} 0 R /F3 ${mono} 0 R >> >> /Contents ${content} 0 R >>`));});objects[1]=`<< /Type /Pages /Kids [${pages.map(p=>p+' 0 R').join(' ')}] /Count ${pages.length} >>`;
 let pdf='%PDF-1.4\n',offsets=[0];objects.forEach((obj,i)=>{offsets.push(pdf.length);pdf+=`${i+1} 0 obj\n${obj}\nendobj\n`;});const start=pdf.length;pdf+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`;for(const off of offsets.slice(1))pdf+=String(off).padStart(10,'0')+' 00000 n \n';pdf+=`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF\n`;return new TextEncoder().encode(pdf);
}
